<?php
require_once __DIR__ . '/includes/functions.php';
$slug = trim((string) ($_GET['slug'] ?? ''));
$stmt = db()->prepare('SELECT p.*,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.slug=? AND p.is_active=1 LIMIT 1');
$stmt->execute([$slug]);
$product = $stmt->fetch();
if (!$product) { http_response_code(404); $pageTitle = 'Fabric not found | Yucca Fabrics'; require __DIR__ . '/includes/header.php'; echo '<section class="mx-auto max-w-3xl px-5 py-24 text-center"><h1 class="font-serif text-4xl">We couldn’t find that fabric</h1><a class="mt-6 inline-block underline" href="' . e(url('shop.php')) . '">Back to the collection</a></section>'; require __DIR__ . '/includes/footer.php'; exit; }
$photos = db()->prepare('SELECT image,alt_text FROM product_images WHERE product_id=? ORDER BY sort_order,id');
$photos->execute([$product['id']]);
$images = $photos->fetchAll();
$price = $product['sale_price'] !== null ? (float) $product['sale_price'] : (float) $product['price'];
$relatedStmt = db()->prepare('SELECT p.*, c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.category_id=? AND p.id<>? AND p.is_active=1 LIMIT 4');
$relatedStmt->execute([$product['category_id'], $product['id']]);
$related = $relatedStmt->fetchAll();
$reviewStmt=db()->prepare("SELECT pr.rating,pr.title,pr.review,pr.created_at,u.name FROM product_reviews pr JOIN users u ON u.id=pr.user_id WHERE pr.product_id=? AND pr.status='approved' ORDER BY pr.created_at DESC LIMIT 10");
$reviewStmt->execute([$product['id']]);$reviews=$reviewStmt->fetchAll();
$canReview=false;
if(current_user()&&current_user()['role']==='customer'){$eligible=db()->prepare("SELECT o.id FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.user_id=? AND oi.product_id=? AND o.status='delivered' LIMIT 1");$eligible->execute([current_user()['id'],$product['id']]);$canReview=(bool)$eligible->fetchColumn();}
$pageTitle = $product['name'] . ' | Yucca Fabrics';
$schemaImage=$product['image']?absolute_url('uploads/products/'.rawurlencode(basename($product['image']))):'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=900&q=80';
$structuredData=['@context'=>'https://schema.org','@type'=>'Product','name'=>$product['name'],'description'=>$product['description'],'sku'=>$product['sku'],'image'=>$schemaImage,'offers'=>['@type'=>'Offer','priceCurrency'=>CURRENCY,'price'=>(string)$price,'availability'=>(int)$product['stock']>0?'https://schema.org/InStock':'https://schema.org/OutOfStock','url'=>absolute_url('product-details.php?slug='.rawurlencode($product['slug']))]];
require __DIR__ . '/includes/header.php';
?>
<div class="mx-auto max-w-7xl px-5 py-10"><p class="text-xs text-gray-500"><a href="<?= e(url('shop.php')) ?>">Shop fabrics</a> / <?= e($product['category_name'] ?? 'Collection') ?></p>
<section class="mt-7 grid gap-10 md:grid-cols-2"><div><img id="product-image" class="aspect-[4/5] w-full bg-white object-cover" src="<?= e(product_image($product['image'])) ?>" alt="<?= e($product['name']) ?>"><?php if ($images): ?><div class="mt-3 flex gap-3"><?php foreach ($images as $image): ?><button type="button" class="h-20 w-20 overflow-hidden border border-black/10" data-image="<?= e(url('uploads/products/' . rawurlencode(basename($image['image'])))) ?>"><img src="<?= e(url('uploads/products/' . rawurlencode(basename($image['image'])))) ?>" alt="<?= e($image['alt_text'] ?: $product['name']) ?>" class="h-full w-full object-cover"></button><?php endforeach; ?></div><?php endif; ?></div>
<div class="py-3 md:py-10"><p class="eyebrow"><?= e($product['category_name'] ?? 'Yucca collection') ?></p><h1 class="mt-3 font-serif text-4xl sm:text-5xl"><?= e($product['name']) ?></h1><p class="mt-3 text-xs text-gray-500">SKU <?= e($product['sku']) ?></p><p class="mt-5 text-sm leading-7 text-gray-600"><?= nl2br(e($product['description'])) ?></p><div class="mt-6 grid grid-cols-2 gap-y-3 border-y border-black/10 py-5 text-sm"><span class="text-gray-500">Colour</span><span><?= e($product['colour'] ?: 'Ask us') ?></span><span class="text-gray-500">Material</span><span><?= e($product['material'] ?: 'See description') ?></span><span class="text-gray-500">Availability</span><span><?= (int) $product['stock'] > 0 ? 'In stock · ' . (int) $product['stock'] . ' ' . e($product['unit']) : 'Currently unavailable' ?></span></div>
<?php if ((int) $product['stock'] > 0): ?><div class="mt-7 flex flex-wrap items-center gap-3"><label class="text-sm" for="quantity">Quantity (<?= e($product['unit']) ?>)</label><input id="quantity" name="quantity" type="number" min="1" max="<?= (int) $product['stock'] ?>" value="1" class="form-control w-24"><button data-add-cart="<?= (int) $product['id'] ?>" class="rounded-full bg-forest px-7 py-3 text-sm font-semibold text-white">Add to bag</button></div><?php endif; ?><p class="mt-5 text-xs leading-5 text-gray-500">Need help choosing? <a class="underline" href="<?= e(url('consultations.php')) ?>">Book a fabric consultation</a> and we’ll find the right fit.</p></div></section>
<section class="mt-12 border-t border-black/10 py-12"><h2 class="font-serif text-3xl">Notes from customers</h2><?php if($reviews): ?><div class="mt-6 grid gap-4 md:grid-cols-2"><?php foreach($reviews as $review): ?><article class="bg-white p-5"><p class="text-clay"><?= str_repeat('★',(int)$review['rating']) ?><span class="text-gray-300"><?= str_repeat('★',5-(int)$review['rating']) ?></span></p><?php if($review['title']): ?><h3 class="mt-2 font-semibold"><?= e($review['title']) ?></h3><?php endif; ?><p class="mt-2 text-sm leading-6 text-gray-600"><?= e($review['review']) ?></p><p class="mt-3 text-xs text-gray-500"><?= e($review['name']) ?> · <?= e(date('M Y',strtotime($review['created_at']))) ?></p></article><?php endforeach; ?></div><?php else: ?><p class="mt-4 text-sm text-gray-600">No customer notes yet.</p><?php endif; ?>
<?php if($canReview): ?><form data-ajax-form action="<?= e(url('api/reviews.php')) ?>" method="post" class="mt-8 grid max-w-xl gap-3 bg-white p-5"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><h3 class="font-serif text-xl">Share your experience</h3><label class="text-sm">Rating<select class="form-control mt-1" name="rating" required><option value="5">5 — Loved it</option><option value="4">4 — Very good</option><option value="3">3 — Good</option><option value="2">2 — Not for me</option><option value="1">1 — Disappointed</option></select></label><label class="text-sm">Title (optional)<input class="form-control mt-1" name="title" maxlength="150"></label><label class="text-sm">Your review<textarea class="form-control mt-1" name="review" minlength="10" maxlength="2000" rows="4" required></textarea></label><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white">Submit for review</button></form><?php elseif(current_user()&&current_user()['role']==='customer'): ?><p class="mt-6 text-xs text-gray-500">Verified product reviews are available after a delivered order.</p><?php endif; ?></section>
<?php if ($related): ?><section class="py-16"><h2 class="font-serif text-3xl">You might also like</h2><div class="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><?php foreach($related as $product): require __DIR__ . '/includes/product-card.php'; endforeach; ?></div></section><?php endif; ?>
</div>
<script>document.querySelectorAll('[data-image]').forEach(button=>button.addEventListener('click',()=>document.getElementById('product-image').src=button.dataset.image));</script>
<?php require __DIR__ . '/includes/footer.php'; ?>
